        const std::vector<unsigned int>& indices,
        AABB aabb);
    ~OpenGLMesh();

    void draw() const;
	void drawInstanced(uint32_t instanceCount) const;
    AABB aabb;

private:
    GLuint VAO, VBO, EBO;
    unsigned int indexCount;
};
